<div class="page-heading"><div><p class="eyebrow">YOUR INBOX</p><h1>Care updates.</h1><p class="page-lead">Assignments, submitted evidence, and review decisions appear here when you reload or return to this page.</p></div><span class="date-chip"><?= icon('bell', 'size-4') ?> <?= $unreadUpdateCount ?> unread</span></div>
<?php if (!$updates): ?><section class="surface-card grave-empty"><div class="next-illustration" aria-hidden="true"><?= icon('bell', 'size-10') ?></div><h2>No updates yet</h2><p>Updates will appear here as care requests move forward.</p></section><?php else: ?><div class="update-list"><?php foreach ($updates as $item): ?><article class="surface-card update-card<?= $item['read_at'] ? '' : ' is-unread' ?>"><span class="update-card-icon" aria-hidden="true"><?= icon('bell', 'size-5') ?></span><div><p class="eyebrow">REQUEST #<?= (int) $item['request_id'] ?><?= $item['read_at'] ? '' : ' · NEW' ?></p><h2><?= e($item['message']) ?></h2><small><?= e(date('M j, Y · g:i A', strtotime($item['created_at']))) ?></small></div><form method="post" action="?page=updates"><?= csrf_field() ?><input type="hidden" name="action" value="open_update"><input type="hidden" name="update_id" value="<?= (int) $item['id'] ?>"><button class="btn btn-outline btn-primary btn-sm" type="submit">Open request <?= icon('arrow', 'size-4') ?></button></form></article><?php endforeach; ?></div><?php endif; ?>
